using System.Text.Json;using JobOrbit.Application.DTOs.AdminDepartments;using JobOrbit.Application.DTOs.Jobs;using JobOrbit.Application.Interfaces;using JobOrbit.Domain.Entities;using JobOrbit.Domain.Enums;using Microsoft.EntityFrameworkCore;
namespace JobOrbit.Infrastructure.Persistence.Repositories;public sealed class AdminDepartmentRepository(JobOrbitDbContext db):IAdminDepartmentRepository
{static string?Clean(string?v)=>string.IsNullOrWhiteSpace(v)?null:v.Trim();
public async Task<AdminDepartmentListResult>ListAsync(AdminDepartmentQuery q,CancellationToken t=default){if(q.OrganizationId.HasValue&&!await db.Organizations.AnyAsync(x=>x.Id==q.OrganizationId,t))return new(false,null,true);bool?active=q.Status?.Trim().ToLowerInvariant()switch{"active"=>true,"inactive"=>false,""or null=>null,_=>(bool?)null};if(!string.IsNullOrWhiteSpace(q.Status)&&active is null)return new(false);var rows=db.Departments.AsNoTracking();if(q.OrganizationId.HasValue)rows=rows.Where(x=>x.OrganizationId==q.OrganizationId);if(active.HasValue)rows=rows.Where(x=>x.IsActive==active);if(!string.IsNullOrWhiteSpace(q.Search)){var s=q.Search.Trim();rows=rows.Where(x=>x.Name.Contains(s)||x.Code.Contains(s)||x.Organization.Name.Contains(s));}rows=q.Sort.ToLowerInvariant()switch{"newest"=>rows.OrderByDescending(x=>x.CreatedAt),"oldest"=>rows.OrderBy(x=>x.CreatedAt),"code"=>rows.OrderBy(x=>x.Code),"organization"=>rows.OrderBy(x=>x.Organization.Name).ThenBy(x=>x.Name),_=>rows.OrderBy(x=>x.Name)};var total=await rows.CountAsync(t);var now=DateTime.UtcNow;var items=await rows.Skip((q.Page-1)*q.PageSize).Take(q.PageSize).Select(x=>new AdminDepartmentListItemDto(x.Id,x.OrganizationId,x.Organization.Name,x.Name,x.Code,x.Description,x.IsActive?"Active":"Inactive",0,x.HiringManagers.Count,x.JobPostings.Count(j=>j.Status==JobStatus.Published&&(!j.ClosingAt.HasValue||j.ClosingAt>now)),x.CreatedAt)).ToListAsync(t);return new(true,new PagedResultDto<AdminDepartmentListItemDto>{Items=items,Page=q.Page,PageSize=q.PageSize,TotalItems=total,TotalPages=(int)Math.Ceiling(total/(double)q.PageSize)});}
public Task<AdminDepartmentDetailsDto?>DetailsAsync(int id,CancellationToken t=default){var now=DateTime.UtcNow;return db.Departments.AsNoTracking().Where(x=>x.Id==id).Select(x=>new AdminDepartmentDetailsDto(x.Id,x.OrganizationId,x.Organization.Name,x.Name,x.Code,x.Description,x.Email,x.Phone,x.IsActive?"Active":"Inactive",0,x.HiringManagers.Count,x.JobPostings.Count(j=>j.Status==JobStatus.Published&&(!j.ClosingAt.HasValue||j.ClosingAt>now)),x.JobPostings.SelectMany(j=>j.JobApplications).Count(),x.CreatedAt,x.UpdatedAt)).SingleOrDefaultAsync(t);}
public async Task<IReadOnlyList<DepartmentLookupDto>>LookupAsync(int org,bool inactive,CancellationToken t=default)=>await db.Departments.AsNoTracking().Where(x=>x.OrganizationId==org&&(inactive||x.IsActive)).OrderBy(x=>x.Name).Select(x=>new DepartmentLookupDto(x.Id,x.OrganizationId,x.Name,x.Code,x.IsActive)).ToListAsync(t);
public async Task<AdminDepartmentResult>CreateAsync(int admin,CreateDepartmentRequest r,CancellationToken t=default){var org=await db.Organizations.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==r.OrganizationId,t);if(org is null)return new(AdminDepartmentOutcome.OrganizationNotFound);if(!org.IsActive)return new(AdminDepartmentOutcome.InactiveOrganization);var name=r.Name.Trim();var code=r.Code.Trim().ToUpperInvariant();if(await db.Departments.AnyAsync(x=>x.OrganizationId==r.OrganizationId&&x.Code.ToLower()==code.ToLower(),t))return new(AdminDepartmentOutcome.DuplicateCode);if(await db.Departments.AnyAsync(x=>x.OrganizationId==r.OrganizationId&&x.Name.ToLower()==name.ToLower(),t))return new(AdminDepartmentOutcome.DuplicateName);var x=new Department{OrganizationId=r.OrganizationId,Name=name,Code=code};Apply(x,r);db.Departments.Add(x);await db.SaveChangesAsync(t);db.AuditLogs.Add(new AuditLog{UserId=admin,EntityName=nameof(Department),EntityId=x.Id,Action="AdminCreateDepartment",NewValues=JsonSerializer.Serialize(new{x.OrganizationId,x.Name,x.Code,x.IsActive})});await db.SaveChangesAsync(t);return new(AdminDepartmentOutcome.Success,await DetailsAsync(x.Id,t));}
public async Task<AdminDepartmentResult>UpdateAsync(int admin,int id,UpdateDepartmentRequest r,CancellationToken t=default){var x=await db.Departments.SingleOrDefaultAsync(x=>x.Id==id,t);if(x is null)return new(AdminDepartmentOutcome.NotFound);if(x.OrganizationId!=r.OrganizationId)return new(AdminDepartmentOutcome.UnsafeOrganizationMove);var name=r.Name.Trim();var code=r.Code.Trim().ToUpperInvariant();if(await db.Departments.AnyAsync(d=>d.Id!=id&&d.OrganizationId==x.OrganizationId&&d.Code.ToLower()==code.ToLower(),t))return new(AdminDepartmentOutcome.DuplicateCode);if(await db.Departments.AnyAsync(d=>d.Id!=id&&d.OrganizationId==x.OrganizationId&&d.Name.ToLower()==name.ToLower(),t))return new(AdminDepartmentOutcome.DuplicateName);var old=JsonSerializer.Serialize(new{x.Name,x.Code,x.IsActive});x.Name=name;x.Code=code;Apply(x,r);db.AuditLogs.Add(new AuditLog{UserId=admin,EntityName=nameof(Department),EntityId=id,Action="AdminUpdateDepartment",OldValues=old,NewValues=JsonSerializer.Serialize(new{x.Name,x.Code,x.IsActive})});await db.SaveChangesAsync(t);return new(AdminDepartmentOutcome.Success,await DetailsAsync(id,t));}
public async Task<AdminDepartmentResult>StatusAsync(int admin,int id,UpdateDepartmentStatusRequest r,CancellationToken t=default){var x=await db.Departments.Include(x=>x.Organization).SingleOrDefaultAsync(x=>x.Id==id,t);if(x is null)return new(AdminDepartmentOutcome.NotFound);if(r.IsActive&&!x.Organization.IsActive)return new(AdminDepartmentOutcome.InactiveOrganization);x.IsActive=r.IsActive;x.DeactivatedAt=r.IsActive?null:DateTime.UtcNow;x.DeactivatedReason=r.IsActive?null:Clean(r.Reason);db.AuditLogs.Add(new AuditLog{UserId=admin,EntityName=nameof(Department),EntityId=id,Action=r.IsActive?"AdminActivateDepartment":"AdminDeactivateDepartment",NewValues=JsonSerializer.Serialize(new{r.IsActive,Reason=Clean(r.Reason)})});await db.SaveChangesAsync(t);return new(AdminDepartmentOutcome.Success,await DetailsAsync(id,t));}
static void Apply(Department x,SaveDepartmentRequest r){x.Description=Clean(r.Description);x.Email=Clean(r.Email)?.ToLowerInvariant();x.Phone=Clean(r.Phone);x.IsActive=r.IsActive;if(r.IsActive){x.DeactivatedAt=null;x.DeactivatedReason=null;}else if(!x.DeactivatedAt.HasValue)x.DeactivatedAt=DateTime.UtcNow;}}
